function setRegion(region){if(!['world','europe','usa'].includes(region))return;currentRegion=region;navigation.setRegion(region);document.querySelectorAll('[data-region]').forEach(b=>{b.classList.toggle('active',b.dataset.region===region);b.setAttribute('aria-selected',String(b.dataset.region===region));b.tabIndex=b.dataset.region===region?0:-1;});$('#map-panel').setAttribute('aria-labelledby',region+'-tab');$('#usa-views').hidden=region!=='usa';$('#map').setAttribute('aria-label',regionNames[region]+' comfort map. Click a location for details.');if(meta)headings();discovery?.renderRanking();cityMap?.refresh();}
